<template>
  <div class="dashboard" :class="`role-${role || 'unknown'}`">
    <header class="page-head"><div><span class="eyebrow">{{ roleName }}工作台</span><h1>{{ roleHeadline }}</h1><p class="role-intro">{{ roleIntro }}</p></div><button class="switch" @click="$router.push('/workspaces')">切换角色</button></header>
    <p v-if="error" class="error" role="alert">{{ error }} <button @click="loadSummary">重试</button></p>
    <section class="metric-grid" :aria-label="`${roleName}关键指标`"><article v-for="metric in metrics" :key="metric.label"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.hint }}</small></article></section>
    <div class="work-layout">
      <section class="work-section"><div class="section-heading"><h2>{{ actionTitle }}</h2><span>{{ actions.length }} 个入口</span></div><div class="action-grid"><button v-for="item in actions" :key="item.path" @click="$router.push(item.path)"><strong>{{ item.title }}</strong><span>{{ item.description }}</span><em>进入 →</em></button></div></section>
      <section class="recent"><div class="section-heading"><h2>{{ recentTitle }}</h2><span v-if="recent.length">{{ recent.length }} 条</span></div><div v-if="recent.length" class="recent-list"><div v-for="(item, index) in recent" :key="index" class="recent-row"><strong>{{ item.label }} <small v-if="item.is_demo">演示数据</small></strong><span>{{ item.status_label }}</span></div></div><p v-else class="recent-empty">{{ recentEmptyText }}</p></section>
    </div>
    <p class="note">带“演示数据”标记的记录仅用于流程展示，现场结论以实际检测和登记为准。</p>
  </div>
</template>
<script>
import axios from 'axios';
import { API_BASE } from '@/config/api';
const roleNames={grower:'种植',plant_protection:'植保',harvest:'采收',curing:'烘烤',quality:'收购质检',admin:'管理'};
const roleCopy={grower:['种植作业总览','查看地块健康、天气和营养记录'],plant_protection:['病虫害防控总览','关注识别复核、防治任务与用药记录'],harvest:['采收进度总览','跟踪采收批次、鲜重和送烘烤状态'],curing:['烘烤过程总览','跟踪烤房阶段、温湿度和异常事项'],quality:['收购质检总览','处理待检批次、等级和来源追溯'],admin:['生产运营总览','查看用户、角色和全局业务运行状态']};
const actionsByRole={grower:[{title:'地块农情',description:'地块、天气与生育期',path:'/'},{title:'缺素识别',description:'叶片识别与复核',path:'/recognition'},{title:'施肥记录',description:'基肥与追肥作业',path:'/fertilization'},{title:'营养分析',description:'氮磷钾记录趋势',path:'/analysis/deficiency'}],plant_protection:[{title:'病虫害识别',description:'叶片照片与识别结果',path:'/recognition'},{title:'农药记录',description:'施药与防治对象',path:'/pesticide'},{title:'病害趋势',description:'按地块查看发生情况',path:'/analysis/disease'}],harvest:[{title:'采收批次',description:'叶位、鲜重与入库状态',path:'/harvest'},{title:'AI 作业助手',description:'采收与入库问题咨询',path:'/ai'}],curing:[{title:'烘烤批次',description:'烤房、阶段与温湿度',path:'/curing'},{title:'AI 作业助手',description:'烘烤阶段问题咨询',path:'/ai'}],quality:[{title:'质检记录',description:'称重、复检与来源追溯',path:'/quality'},{title:'AI 作业助手',description:'分级与复检问题咨询',path:'/ai'}],admin:[{title:'用户与角色',description:'账号与岗位权限',path:'/admin'},{title:'AI 作业助手',description:'业务问题咨询',path:'/ai'}]};
const sectionsByRole={grower:['种植工作','最近施肥记录','暂无施肥记录'],plant_protection:['防治工作','最近防治记录','暂无防治记录'],harvest:['采收作业','最近采收批次','暂无采收批次'],curing:['烤房作业','最近烘烤批次','暂无烘烤批次'],quality:['质检作业','最近质检记录','暂无质检记录'],admin:['权限管理','最近采收批次','暂无采收批次']};
export default{data:()=>({metrics:[],recent:[],error:'',role:localStorage.getItem('activeRole')||JSON.parse(localStorage.getItem('roles')||'[]')[0]?.code||''}),computed:{roleName(){return roleNames[this.role]||'生产'},roleHeadline(){return roleCopy[this.role]?.[0]||'生产工作台'},roleIntro(){return roleCopy[this.role]?.[1]||'查看当前岗位的业务信息'},actionTitle(){return sectionsByRole[this.role]?.[0]||'当前工作'},recentTitle(){return sectionsByRole[this.role]?.[1]||'最近记录'},recentEmptyText(){return sectionsByRole[this.role]?.[2]||'暂无记录'},actions(){return actionsByRole[this.role]||[]}},async mounted(){this.onRoleChange=()=>{this.role=localStorage.getItem('activeRole')||'';this.loadSummary()};window.addEventListener('role-change',this.onRoleChange);await this.loadSummary()},beforeUnmount(){window.removeEventListener('role-change',this.onRoleChange)},methods:{async loadSummary(){this.error='';try{const r=await axios.get(`${API_BASE}/workspace/summary/`);this.role=r.data?.data?.role||this.role;this.metrics=r.data?.data?.metrics||[];this.recent=r.data?.data?.recent||[]}catch(e){this.metrics=[];this.recent=[];if(e.response?.status!==401)this.error=e.response?.data?.msg||'工作台数据暂时无法加载，请检查网络后重试'}}}};
</script>
