.dashboard .eyebrow,.dashboard .metric-grid strong,.dashboard .action-grid em{color:var(--role-accent)}.dashboard .page-head{border-bottom-color:var(--role-line)}.dashboard .switch{color:var(--role-accent);border-color:var(--role-line)}.dashboard .metric-grid{margin:18px 0 24px}.dashboard .metric-grid article{border-radius:6px;min-height:104px;padding:15px 17px}.dashboard .metric-grid article:first-child{background:var(--role-soft);border-color:var(--role-line)}
